create extension if not exists pgcrypto;
create table public.tournaments(id uuid primary key default gen_random_uuid(),name text not null default 'King of Chips',status text not null default 'registration' check(status in ('registration','ready','live','completed')),starting_stack int not null default 1000,small_blind int not null default 10,big_blind int not null default 20,hands_per_room int not null default 3,room_capacity int not null default 6,created_at timestamptz not null default now());
create table public.teams(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments on delete cascade,team_name text not null,captain_name text not null,captain_user_id uuid,room_number int,chip_stack int not null default 1000,highest_pot_won int not null default 0,status text not null default 'registered' check(status in ('registered','playing','finished')),created_at timestamptz not null default now(),unique(tournament_id,team_name));
create table public.rooms(id uuid primary key default gen_random_uuid(),tournament_id uuid not null references public.tournaments on delete cascade,room_number int not null,hand_number int not null default 0 check(hand_number between 0 and 3),status text not null default 'ready' check(status in ('ready','playing','completed')),unique(tournament_id,room_number));
create table public.hands(id uuid primary key default gen_random_uuid(),room_id uuid not null references public.rooms on delete cascade,hand_number int not null check(hand_number between 1 and 3),status text not null default 'dealing' check(status in ('dealing','preflop','flop','turn','river','settled')),pot_total int not null default 0,board jsonb not null default '[]',started_at timestamptz not null default now(),settled_at timestamptz,unique(room_id,hand_number));
create table public.hand_seats(id uuid primary key default gen_random_uuid(),hand_id uuid not null references public.hands on delete cascade,team_id uuid not null references public.teams on delete cascade,seat_number int not null,hole_cards jsonb,contribution int not null default 0,folded boolean not null default false,all_in boolean not null default false,unique(hand_id,team_id),unique(hand_id,seat_number));
create table public.hand_actions(id uuid primary key default gen_random_uuid(),hand_id uuid not null references public.hands on delete cascade,team_id uuid not null references public.teams on delete cascade,action_number int not null,action text not null check(action in ('fold','check','call','bet','raise','all_in','timeout')),amount int not null default 0,created_at timestamptz not null default now(),unique(hand_id,action_number));
create table public.hand_results(id uuid primary key default gen_random_uuid(),hand_id uuid not null references public.hands on delete cascade,team_id uuid not null references public.teams on delete cascade,chips_won int not null default 0,hand_rank text,unique(hand_id,team_id));
alter table public.tournaments enable row level security;alter table public.teams enable row level security;alter table public.rooms enable row level security;alter table public.hands enable row level security;alter table public.hand_seats enable row level security;alter table public.hand_actions enable row level security;alter table public.hand_results enable row level security;
-- No anon policies are intentionally provided. Add validated server-side Edge Functions and role-specific RLS policies before production.
